// Employee meals: incremental writeoff during the day, BUKHARA test.
(function(){
 state.mealDishes=[];state.mealQty={};state.mealSummary=[];state.mealBusy=false;state.mealOpenGroups={};
 function actor(){return localStorage.getItem('stolovaya:employee-name')||sessionStorage.getItem('stolovaya:employee-name')||'Буфетчик'}
 const bh=homeScreen;homeScreen=function(){let h=bh();if(state.point!=='BUKHARA')return h;const disabled=state.home?.submitted||state.home?.dayClosed?'disabled':'';const meal=`<button type="button" id="employee-meal-open" ${disabled}><span>♨</span><div><b>Питание</b><small>Бесплатная еда сотрудников</small></div></button>`;if(h.includes('id="kitchen-supply-open"'))return h.replace(/(<button type="button" id="kitchen-supply-open"[\s\S]*?<\/button>)/,`$1${meal}`);return h.replace(/(<section class="home-actions">)/,`$1${meal}`)};
 async function fetchMealSummary(){if(state.point!=='BUKHARA'||!state.token||!state.home)return [];try{state.mealSummary=await rpc('public_employee_meal_summary',{p_token:state.token,p_point_code:state.point,p_business_date:businessDate()})||[]}catch(e){console.warn('employee meal summary',e)}return state.mealSummary}
 const baseLoadPoint=loadPoint;loadPoint=async function(){const r=await baseLoadPoint();await fetchMealSummary();return r};
 async function loadMeal(){state.mealBusy=true;render();try{const [d,s]=await Promise.all([rpc('public_kitchen_supply_dishes',{p_token:state.token,p_point_code:state.point}),rpc('public_employee_meal_summary',{p_token:state.token,p_point_code:state.point,p_business_date:businessDate()})]);state.mealDishes=d||[];state.mealSummary=s||[]}catch(e){state.message=e.message||'Не удалось загрузить питание'}finally{state.mealBusy=false;render()}}
 function summary(id){return state.mealSummary.find(x=>x.dish_id===id)||{} }
 function availableDishes(){return(state.mealDishes||[]).map(d=>{const s=summary(d.dishId);return {...d,available:n(s.available_qty??d.availableQty??d.available??0),already:n(s.total_qty||0)}}).filter(d=>d.available>0||d.already>0)}
 function mealGroups(){const m={};availableDishes().forEach(x=>{const g=clean(x.group||'Прочее')||'Прочее';(m[g]||(m[g]=[])).push(x)});return Object.keys(m).sort((a,b)=>a.localeCompare(b,'ru')).map(name=>({name,items:m[name].sort((a,b)=>clean(a.name).localeCompare(clean(b.name),'ru'))}))}
 function screen(){const groups=mealGroups();return `${header()}${back('Питание')}<section class="question-card"><h2>Бесплатная еда сотрудников</h2><p>Откройте нужную группу, введите количество напротив блюд и нажмите «Сохранить». Новое количество добавится к уже учтённому.</p></section>${state.mealBusy?'<div class="notice">Загрузка…</div>':groups.length?`<div class="meal-groups">${groups.map(g=>{const open=!!state.mealOpenGroups[g.name];const entered=g.items.filter(x=>n(state.mealQty[x.dishId])>0).length;const already=g.items.filter(x=>x.already>0).length;return `<section class="kitchen-group"><button type="button" class="kitchen-group-head" data-meal-group="${esc(g.name)}"><span>${esc(g.name)}</span><span class="kitchen-group-meta">${entered?`введено ${entered} · `:already?`учтено ${already} · `:''}${open?'▲':'▼'}</span></button>${open?`<div class="kitchen-group-body">${g.items.map(x=>`<div class="kitchen-dish"><div class="meal-name"><b>${esc(clean(x.name))}</b><small>Доступно: ${n(x.available)} · Уже учтено: <b>${n(x.already)}</b></small></div><div class="meal-qty"><input data-meal-qty="${x.dishId}" inputmode="decimal" placeholder="0" value="${esc(state.mealQty[x.dishId]||'')}"></div></div>`).join('')}</div>`:''}</section>`}).join('')}</div>`:'<div class="notice">Нет доступных блюд.</div>'}<div class="sticky-action"><button id="employee-meal-save" class="primary" ${state.mealBusy?'disabled':''}>${state.mealBusy?'Сохраняем…':'Сохранить'}</button></div>${state.message?`<p class="toast">${esc(state.message)}</p>`:''}`}
 async function save(){if(state.mealBusy)return;const items=Object.entries(state.mealQty).map(([dishId,q])=>({dishId,qty:n(q)})).filter(x=>x.qty>0);if(!items.length){state.message='Введите количество хотя бы для одного блюда.';render();return}state.mealBusy=true;state.message='';render();try{for(const x of items)await rpc('public_add_employee_meal',{p_token:state.token,p_point_code:state.point,p_dish_id:x.dishId,p_quantity:x.qty,p_actor:actor(),p_business_date:businessDate()});state.mealQty={};await loadPoint();await loadMeal();state.message='Питание сохранено. Количество добавлено к уже учтённому.';render()}catch(e){state.message=e.message||'Не удалось сохранить';state.mealBusy=false;render()}}
 const bc=closingCard;closingCard=function(x){let h=bc(x);if(state.point!=='BUKHARA')return h;const q=n(summary(x.dish_id).total_qty||0);if(q<=0)return h;return h.replace('<div class="fields">',`<div class="meal-closing-info">Питание сотрудников: <b>${fmt(q)}</b></div><div class="fields">`)};
 const br=render;render=function(){if(state.screen==='employee-meal'){app.innerHTML=screen();bind();return}br()};
 const bb=bind;bind=function(){bb();document.getElementById('employee-meal-open')?.addEventListener('click',()=>{state.screen='employee-meal';state.message='';state.mealOpenGroups={};render();loadMeal()});document.querySelectorAll('[data-meal-group]').forEach(b=>b.onclick=()=>{const g=b.dataset.mealGroup;state.mealOpenGroups[g]=!state.mealOpenGroups[g];render()});document.querySelectorAll('[data-meal-qty]').forEach(inp=>inp.oninput=e=>{const v=e.target.value.replace(',','.');if(v&&!/^\d*(\.\d{0,3})?$/.test(v))return;state.mealQty[inp.dataset.mealQty]=v});document.getElementById('employee-meal-save')?.addEventListener('click',save)};
 const st=document.createElement('style');st.textContent='.meal-groups{display:flex;flex-direction:column;gap:9px;margin-bottom:90px}.meal-name{display:flex;flex-direction:column;gap:4px;min-width:0}.meal-name small{color:#68716b}.meal-qty input{width:82px;min-width:82px;text-align:center;font-size:18px}.meal-closing-info{margin:8px 0 10px;padding:8px 10px;border-radius:10px;background:#f3f6f1;color:#496052;font-size:14px}.meal-closing-info b{font-size:16px;color:#315f49}';document.head.appendChild(st);
})();